};

/**
 * @method
 * @name scwin.detail
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_sprtRoomNo index init
 * @returns
 * @hidden N
*/
scwin.detail = async function (ipt_sprtRoomNo, index, init) {
    /* sdd-asis-lifecycle:begin fn_detail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#ipt_sprtRoomNo', $('#searchForm')).val(ipt_sprtRoomNo);
