};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param ipt_pageIndex
 * @returns
 * @hidden N
*/
scwin.search = async function (ipt_pageIndex) {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (ipt_pageIndex) {
        $('#ipt_pageIndex', $('#searchForm')).val(ipt_pageIndex);
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_startDate', $('#searchForm')).val())) {
        await alertE("시작일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_endDate', $('#searchForm')).val() !== "" && !$c.date.isDate($('#ipt_endDate', $('#searchForm')).val())) {
        await alertE("종료일자 형식이 틀립니다.");
        return;
    }
    if ($('#ipt_startDate', $('#searchForm')).val() !== "" && $('#ipt_endDate', $('#searchForm')).val() !== "" && $('#ipt_startDate', $('#searchForm')).val() > $('#ipt_endDate', $('#searchForm')).val()) {
        await alertE("시작일자는 종료일자 이전 이여야 합니다.");
        return;
    }
    blockLoading();
    $('#ipt_SCREN_ID', $('#searchForm')).val("/jldods27000/jldods27000.xml");
    $('#ipt_method', $('#searchForm')).val("readResourceRoomList");
    $('#searchForm').submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fileDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param sprt_room_no attach_seq attach_file_nm
 * @returns
 * @hidden N
*/
scwin.fileDownload = function (sprt_room_no, attach_seq, attach_file_nm) {
    /* sdd-asis-lifecycle:begin fn_fileDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $('#ipt_sprtRoomNo', $('#attachForm')).val(sprt_room_no);
    $('#ipt_attachSeq', $('#attachForm')).val(attach_seq);
    $('#ipt_attachFileNm', $('#attachForm')).val(attach_file_nm);
    $('#ipt_SCREN_ID', $('#attachForm')).val("/jldods25000/jldods25000.xml");
    $('#ipt_method', $('#attachForm')).val("searchBbsAttachFile");
    $('#attachForm').submit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.chkboxAll
 * @author Inswave
 * @date 2026. 09. 29
 * @param allChecked
 * @returns
 * @hidden N
*/
scwin.chkboxAll = function (allChecked) {
    /* sdd-asis-lifecycle:begin fn_chkboxAll — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (allChecked) {
        $("input[name=sprtRoomGrpIdArr]", $('#searchForm')).prop("checked", true);
    } else {
        $("input[name=sprtRoomGrpIdArr]", $('#searchForm')).prop("checked", false);
    }
    /* sdd-asis-lifecycle:end */
};


function chkboxAllChk() {
    /* sdd-asis-lifecycle:begin fn_chkboxAllChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let cnt = 0;
    const totCnt = $("input[name=sprtRoomGrpIdArr]", $('#searchForm')).length - 1;
    $("input[name=sprtRoomGrpIdArr]", $('#searchForm')).each(function() {
            if (this.value !== "ALL" && this.checked) {
                cnt++;
            }
    });
    if (cnt === totCnt) {
        $("input[id=ipt_sprtRoomGrpIdAll]", $('#searchForm')).prop("checked", true);
    } else {
        $("input[id=ipt_sprtRoomGrpIdAll]", $('#searchForm')).prop("checked", false);
    }
    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }


